-- Owner-only OFFLINE/restore rehearsal query; no tokens, ciphertext or prose emitted.
-- Run only in a separately authorized isolated restore, never scout_live.
SELECT CASE WHEN current_database()='unfarmd_v4_pilot' THEN jsonb_build_object(
 'journal',coalesce((SELECT jsonb_agg(jsonb_build_object('id',encode(sha256(convert_to(owner_id::text||'/'||journal_id::text,'UTF8')),'hex'),'revision',revision,'head',head) ORDER BY owner_id,journal_id) FROM unfarmd_journal.journals WHERE head IS NOT NULL),'[]'::jsonb),
 'tombstones',coalesce((SELECT jsonb_agg(jsonb_build_object('id',encode(sha256(convert_to(owner_id::text||'/'||journal_id::text,'UTF8')),'hex'),'head',head) ORDER BY owner_id,journal_id) FROM unfarmd_v4_deploy.tombstones),'[]'::jsonb),
 'owners',coalesce((SELECT jsonb_agg(jsonb_build_object('id',encode(sha256(convert_to(owner_id::text,'UTF8')),'hex'),'journals',journals,'events',lifetime_events) ORDER BY owner_id) FROM unfarmd_journal.owners),'[]'::jsonb),
 'rates',coalesce((SELECT jsonb_agg(jsonb_build_object('id',encode(sha256(convert_to(owner_id::text,'UTF8')),'hex'),'windowAt',floor(extract(epoch FROM window_at)*1000)::bigint,'lastAt',floor(extract(epoch FROM last_at)*1000)::bigint,'reads',reads,'writes',writes) ORDER BY owner_id) FROM unfarmd_thesis_rate.usage),'[]'::jsonb),
 'authHash',encode(sha256(convert_to(jsonb_build_object('policy',(SELECT jsonb_agg(to_jsonb(p)) FROM unfarmd_v4_owner.policy p),'sessionDigests',(SELECT jsonb_agg(encode(sha256(convert_to(to_jsonb(s)::text,'UTF8')),'hex') ORDER BY id) FROM public.v4_owner_session s))::text,'UTF8')),'hex'),
 'pilot',(SELECT jsonb_build_object('policyHash',p.hash,'reads',s.reads,'attempts',s.attempts,'credits',s.credits,'stopped',s.stopped,'fence',CASE WHEN s.fence IS NULL THEN NULL ELSE encode(sha256(convert_to(s.fence::text,'UTF8')),'hex') END,'leaseHash',CASE WHEN s.lease IS NULL THEN NULL ELSE encode(sha256(convert_to(s.lease::text,'UTF8')),'hex') END,'historyHash',encode(sha256(convert_to(jsonb_build_object('history',(SELECT jsonb_agg(to_jsonb(h) ORDER BY seq) FROM unfarmd_v4_pilot.history h),'permits',(SELECT jsonb_agg(to_jsonb(m) ORDER BY id) FROM unfarmd_v4_pilot.permits m),'reports',(SELECT jsonb_agg(to_jsonb(r) ORDER BY mint) FROM unfarmd_v4_pilot.reports r))::text,'UTF8')),'hex')) FROM unfarmd_v4_pilot.policy p JOIN unfarmd_v4_pilot.state s USING(singleton))
) ELSE NULL END AS snapshot;
